#!/usr/bin/env node
import fs from 'node:fs';import{spawnSync}from'node:child_process';
const OP='COMPASS_MIRRORLAND_CRYSTAL_ANIMATION_MODERNIZATION_PERFORMANCE_CONTINUATION_GEN1531',LOCK=1531,BASE='74de0882af55fed53272a191b173e45f5cdbd551',OUT=process.env.COMPASS_PERFORMANCE_OUTPUT||'/tmp/compass-gen1531-performance.json';
const git=a=>spawnSync('git',a,{encoding:'utf8'}),read=p=>fs.readFileSync(p,'utf8'),checks=[],check=(id,pass,evidence)=>checks.push({id,pass:Boolean(pass),evidence});
const head=git(['rev-parse','HEAD^{commit}']).stdout.trim(),expected=(process.env.COMPASS_CANDIDATE_HEAD||head).trim();check('EXACT_HEAD',head===expected,{head,expected});check('BASE_ANCESTOR',git(['merge-base','--is-ancestor',BASE,head]).status===0,{BASE,head});
const changed=git(['diff','--name-only',`${BASE}...${head}`]).stdout.trim().split(/\r?\n/).filter(Boolean),allowed=new Set(['assets/compass/compass.crystals.js','assets/compass/compass.mirrorland-window.js','.github/ai-router/projects/compass/verify-performance-successor.mjs','.github/ai-router/projects/compass/verify-display-continuity.v1.mjs','.github/workflows/compass-performance-successor-validation.yml','.github/workflows/compass-carousel-successor-live-qualification.yml']);check('EXACT_SCOPE',changed.length>=2&&changed.every(p=>allowed.has(p)),changed);
for(const p of ['assets/compass/compass.identity-3d.js','assets/compass/compass.brain-scene.js','assets/compass/upstream-compass.renderer.js','assets/compass/compass.controller.js'])check(`PROTECTED_${p.split('/').pop().replace(/\W/g,'_').toUpperCase()}`,git(['diff','--quiet',BASE,head,'--',p]).status===0,p);
const m=read('assets/compass/compass.mirrorland-window.js'),c=read('assets/compass/compass.crystals.js');
check('MIRRORLAND_DEMAND_DRIVEN',m.includes('function transitionNeedsFrames()')&&m.includes('function requestRender()')&&m.includes('if (transitionNeedsFrames())')&&m.includes('DGB_MIRRORLAND_WINDOW_REVEAL_REQUEST')&&m.includes('DGB_MIRRORLAND_WINDOW_WITHDRAW_REQUEST'),'reveal/withdraw only continuous scheduling');
check('MIRRORLAND_IDENTITY_PRESERVED',m.includes('SELF_CONTAINED_2D_CRYSTALLINE_STAINED_GLASS')&&m.includes('paneCount')&&m.includes('MIRRORLAND_WINDOW_REVEAL_COMPLETE')&&m.includes('MIRRORLAND_WINDOW_WITHDRAWAL_COMPLETE'),'stained glass + lifecycle');
check('CRYSTAL_DEMAND_DRIVEN',c.includes('function needsAnotherFrame()')&&c.includes('function requestRender()')&&c.includes('function bindRenderInvalidation()')&&c.includes('MutationObserver')&&c.includes('SETTLE_EPSILON'),'interaction/convergence/invalidation scheduling');
check('CRYSTAL_TOPOLOGY_PRESERVED',c.includes('registryCardinalCount')&&c.includes('registryRoomCount')&&c.includes('sphericalConstellationEnabled'),'cardinal/room semantic renderer retained');
check('NO_PERPETUAL_MIRRORLAND_CONTINUATION',!m.includes('drawWindow();\n\n    requestRender();\n  }'),'no unconditional mirror continuation');check('NO_PERPETUAL_CRYSTAL_CONTINUATION',!c.includes('emitReceipt({\n      status:\n        "available"')||c.includes('if (needsAnotherFrame())'),'crystal continuation gated');
const failures=checks.filter(x=>!x.pass),receipt={schema:'COMPASS_GEN1531_PERFORMANCE_RECEIPT_v1',operationId:OP,lockGeneration:LOCK,governingHead:BASE,candidateHead:head,result:failures.length?'FAIL_CLOSED':'PASS_CLOSED',checks,failures:failures.map(x=>x.id)};fs.writeFileSync(OUT,JSON.stringify(receipt,null,2)+'\n');console.log(JSON.stringify(receipt,null,2));if(failures.length)process.exit(1);
